class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int l = 0, r = nums.length - 1;
        while (l < r) {
            if (nums[l] % 2 == 1 && nums[r] % 2 == 0) {
                int tmp = nums[l];
                nums[l] = nums[r];
                nums[r] = tmp;
            }
            if (nums[l] % 2 == 0) l++;
            if (nums[r] % 2 == 1) r--;
        }
        return nums;
    }
}

class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int write = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] % 2 == 0) {
                int tmp = nums[write];
                nums[write] = nums[i];
                nums[i] = tmp;
                write++;
            }
        }
        return nums;
    }
}

class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int[] result = new int[nums.length];
        int write = 0;
        for (int value : nums) {
            if (value % 2 == 0) {
                result[write++] = value;
            }
        }
        for (int value : nums) {
            if (value % 2 != 0) {
                result[write++] = value;
            }
        }
        return result;
    }
}

class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int[] result = new int[nums.length];
        int left = 0;
        int right = nums.length - 1;
        for (int value : nums) {
            if (value % 2 == 0) {
                result[left++] = value;
            } else {
                result[right--] = value;
            }
        }
        return result;
    }
}

class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int[] counts = new int[5001];
        for (int value : nums) {
            counts[value]++;
        }

        int[] result = new int[nums.length];
        int write = 0;
        for (int value = 0; value <= 5000; value += 2) {
            while (counts[value] > 0) {
                result[write++] = value;
                counts[value]--;
            }
        }
        for (int value = 1; value <= 5000; value += 2) {
            while (counts[value] > 0) {
                result[write++] = value;
                counts[value]--;
            }
        }
        return result;
    }
}
